<script setup lang="ts">
import RecordPagination from '../components/RecordPagination.vue'
const releaseSize = ref(20)
import {computed,onMounted,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessageBox,ElMessage} from 'element-plus'
import * as api from '../api/delivery'
import type {Release,Releases} from '../api/delivery'
import * as training from '../api/training'
import type {Model} from '../api/training'
import {organizations} from '../api/workbench'
import {session} from '../session'
const route=useRoute(),admin=computed(()=>session.user?.role==='ADMIN'),data=ref<Releases>(),page=ref(1),error=ref(''),busy=ref(false),departments=ref<Array<{organizationId:string;name:string}>>([]),models=ref<Model[]>([]),evaluations=ref<Array<{runId:string;name:string}>>([]),predictionResult=ref<api.ReleasedResult>()
const form=reactive({organizationId:'0',scene:route.query.modelId?'PAIR_PREDICTION':'TEXT_REUSE',name:'',modelId:String(route.query.modelId??''),evaluationId:'',preset:'CURRENT',profileId:''}),prediction=reactive({organizationId:'',sentence1:'',sentence2:''})
const activeTab=ref(admin.value&&route.query.modelId?'new':'current')
const historyPage=ref(1),historySize=ref(20),historyTotal=ref(0),historyRows=ref<Releases['history']>([])
async function loadHistory(){try{const result=await api.releaseHistory(historyPage.value,historySize.value);historyRows.value=result.items;historyTotal.value=result.total}catch(v){error.value=v instanceof Error?v.message:'读取切换历史失败'}}
watch(activeTab,tab=>{if(tab==='history')void loadHistory()})
const profiles=ref<api.TextProfile[]>([]),profilesLoading=ref(false),profilesLoaded=ref(false)
async function loadProfiles(){if(profilesLoading.value)return;profilesLoading.value=true;try{profiles.value=(await api.textProfiles()).items;profilesLoaded.value=true;if(form.profileId&&!profiles.value.some(p=>p.profileId===form.profileId))form.profileId=''}catch(v){error.value=v instanceof Error?v.message:'读取校园模型失败'}finally{profilesLoading.value=false}}
async function chooseModel(){form.evaluationId='';evaluations.value=form.modelId?await api.releaseEvaluations(form.modelId):[]}
async function searchModels(q:string){try{models.value=(await training.models(1,q)).items}catch(v){error.value=v instanceof Error?v.message:'读取模型失败'}}
let timer:ReturnType<typeof setInterval>|undefined,alive=true,refreshing=false
async function load(){if(refreshing)return;refreshing=true;try{const value=await api.releases(page.value,releaseSize.value);if(alive)data.value=value}catch(v){error.value=v instanceof Error?v.message:'读取版本失败'}finally{refreshing=false}}
async function perform(task:()=>Promise<void>){busy.value=true;error.value='';try{await task()}catch(v){error.value=v instanceof Error?v.message:'操作未完成'}finally{busy.value=false}}
function expected(row:Release){return data.value?.pointers.find(p=>p.scopeKey===`${row.organizationId}:${row.scene}`)?.releaseId??''}
async function register(){await perform(async()=>{if(!form.name.trim())throw new Error('请填写版本名称');if(form.scene==='TEXT_REUSE'&&form.preset==='CAMPUS_V3'&&!form.profileId)throw new Error('请选择校园模型版本');await api.createRelease({...form});ElMessage.success('已提交核验');activeTab.value='current';await load()})}
async function switchVersion(row:Release){try{await ElMessageBox.confirm(`将${row.department}的${api.sceneNames[row.scene]}切换为“${row.name}”？`,'发布 / 回退',{confirmButtonText:'确认切换',cancelButtonText:'取消'})}catch{return}await perform(async()=>{await api.activate(row.id,expected(row));ElMessage.success('活动版本已切换');await load()})}
async function removeOverride(row:Release){try{await ElMessageBox.confirm('确认撤销该场景的专用版本，恢复默认选择？','恢复默认',{confirmButtonText:'恢复默认',cancelButtonText:'取消'})}catch{return}await perform(async()=>{await api.reset(row.organizationId,row.scene,expected(row));await load()})}
async function predict(){await perform(async()=>{if(!prediction.organizationId||!prediction.sentence1.trim()||!prediction.sentence2.trim())throw new Error('请选择部门并填写两段文本');predictionResult.value=await api.releasedPredict(prediction.organizationId,[{sentence1:prediction.sentence1,sentence2:prediction.sentence2}])})}
const releaseName=(id:string|null)=>id?data.value?.items.find(r=>r.id===id)?.name??id.slice(0,8):'默认选择'
onMounted(()=>{void perform(async()=>{const [orgs,modelList]=await Promise.all([organizations(),training.models()]);departments.value=orgs;prediction.organizationId=orgs[0]?.organizationId??'';models.value=modelList.items;if(form.modelId)await chooseModel();await load()});timer=setInterval(()=>void load(),3000)});onBeforeUnmount(()=>{alive=false;if(timer)clearInterval(timer)})
</script>
<template><div class="page-toolbar"><p class="muted">按部门和使用场景管理生效版本，保留每次切换记录。</p><el-button v-if="admin" type="primary" @click="activeTab='new'">登记新版本</el-button></div><el-tabs v-model="activeTab" class="workspace-tabs"><el-tab-pane label="当前版本与切换" name="current"/><el-tab-pane v-if="admin" label="登记发布" name="new"/><el-tab-pane label="试用已发布模型" name="try"/><el-tab-pane label="切换历史" name="history"/></el-tabs><el-alert v-if="error" :title="error" type="error" :closable="false"/><section v-show="activeTab==='current'" class="panel"><div class="section-heading"><h2>当前生效版本</h2><el-button @click="load">刷新</el-button></div><div class="release-pointers"><div v-for="p in data?.pointers.filter(p=>p.releaseId)" :key="p.scopeKey"><span>{{p.scopeKey.startsWith('0:')?'校级默认':departments.find(d=>d.organizationId===p.scopeKey.split(':')[0])?.name}} · {{api.sceneNames[p.scopeKey.split(':')[1]!]}}</span><strong>{{releaseName(p.releaseId)}}</strong></div></div><el-empty v-if="!data?.pointers.some(p=>p.releaseId)" description="当前沿用默认审核配置，可登记版本后发布" :image-size="60"/></section>
<section v-if="admin" v-show="activeTab==='new'" class="panel"><h2>登记发布版本</h2><p class="section-intro">选择使用场景与范围，关联兼容模型和评价，核验通过后再发布。</p><div class="report-summary"><div><strong>{{ form.scene==='PAIR_PREDICTION'?'句对预测':'整篇正文审核' }}</strong><p>{{ form.scene==='PAIR_PREDICTION'?'使用网页训练的分类模型比较两段文本。':'选择能够检索来源、对齐片段的正文审核配置。' }}</p></div></div><el-form label-position="top"><div class="release-form"><el-form-item label="版本名称"><el-input v-model="form.name" maxlength="120"/></el-form-item><el-form-item label="使用范围"><el-select v-model="form.organizationId"><el-option value="0" label="校级默认"/><el-option v-for="d in departments" :key="d.organizationId" :value="d.organizationId" :label="d.name"/></el-select></el-form-item><el-form-item label="使用场景"><el-select v-model="form.scene"><el-option v-for="(name,key) in api.sceneNames" :key="key" :value="key" :label="name"/></el-select></el-form-item><el-form-item v-if="form.scene==='TEXT_REUSE'" label="兼容审核配置"><el-select v-model="form.preset" @change="form.preset==='CAMPUS_V3' &amp;&amp; loadProfiles()"><el-option value="CURRENT" label="句子对齐语义审核"/><el-option value="LEGACY" label="原有字面审核配置"/><el-option value="CAMPUS_V3" label="正式校园模型（BGE + M3）"/></el-select></el-form-item><template v-else><el-form-item label="已训练模型"><el-select v-model="form.modelId" filterable remote :remote-method="searchModels" @change="perform(chooseModel)"><el-option v-for="m in models" :key="m.modelId" :value="m.modelId" :label="m.name"/></el-select></el-form-item><el-form-item label="独立评价"><el-select v-model="form.evaluationId" placeholder="先在模型管理完成独立评价"><el-option v-for="r in evaluations" :key="r.runId" :value="r.runId" :label="r.name || r.runId.slice(0,8)"/></el-select></el-form-item></template><el-form-item v-if="form.scene==='TEXT_REUSE' &amp;&amp; form.preset==='CAMPUS_V3'" label="校园模型版本"><el-select v-model="form.profileId" :loading="profilesLoading" placeholder="选择已准备的模型版本"><el-option v-for="p in profiles" :key="p.profileId" :value="p.profileId" :label="`${p.name} · 参考库 ${p.libraryGenerationId}`"/></el-select><el-button link :loading="profilesLoading" @click="loadProfiles">刷新版本</el-button><span v-if="profilesLoaded &amp;&amp; !profiles.length">暂无准备完成的校园模型版本</span></el-form-item></div></el-form><el-button type="primary" :loading="busy" @click="register">核验并登记</el-button><RouterLink to="/models" class="link-gap">查看模型及评价</RouterLink></section>
<section v-show="activeTab==='current'" class="panel"><h2>发布版本与回退</h2><el-table :data="data?.items ?? []" empty-text="暂无发布版本"><el-table-column prop="name" label="版本" min-width="180"/><el-table-column prop="department" label="范围" min-width="140"/><el-table-column label="场景" width="120"><template #default="{row}">{{api.sceneNames[row.scene]}}</template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="expected(row)===row.id?'success':row.status==='FAILED'?'danger':'info'">{{expected(row)===row.id?'使用中':api.deliveryStates[row.status]}}</el-tag></template></el-table-column><el-table-column label="核验与评价" min-width="220"><template #default="{row}"><span v-if="row.error" class="unsaved">{{row.error}}</span><span v-else-if="row.manifest?.metrics">Macro-F1 {{(row.manifest.metrics.macro_f1*100).toFixed(2)}}% · 阈值 {{row.manifest.threshold}}</span><span v-else>{{row.manifest?.textConfig?.method || '等待核验'}}<template v-if="row.manifest?.profileId"> · 参考库 {{row.manifest.libraryGenerationId}}</template></span></template></el-table-column><el-table-column v-if="admin" label="操作" width="200"><template #default="{row}"><el-button link :disabled="busy||row.status!=='READY'||expected(row)===row.id" @click="switchVersion(row)">发布 / 回退</el-button><el-button v-if="expected(row)===row.id" link :disabled="busy" @click="removeOverride(row)">恢复默认</el-button></template></el-table-column></el-table><RecordPagination v-model:current-page="page" v-model:page-size="releaseSize" :total="data?.total??0" @change="load" /></section>
<section v-show="activeTab==='try'" class="panel"><h2>使用已发布句对模型预测</h2><el-form label-position="top"><el-form-item label="使用部门"><el-select v-model="prediction.organizationId"><el-option v-for="d in departments" :key="d.organizationId" :value="d.organizationId" :label="d.name"/></el-select></el-form-item><div class="prediction-pair"><el-form-item label="原文"><el-input v-model="prediction.sentence1" type="textarea" :rows="3"/></el-form-item><el-form-item label="待比对文本"><el-input v-model="prediction.sentence2" type="textarea" :rows="3"/></el-form-item></div></el-form><el-button type="primary" :loading="busy" @click="predict">按活动版本预测</el-button><div v-if="predictionResult" class="release-pointers"><div><span>发布版本 {{predictionResult.releaseId.slice(0,8)}}</span><strong>{{predictionResult.rows[0]?.predicted===1?'语义相近':'语义不同'}}</strong></div><div><span>{{predictionResult.rows[0]?.scoreType==='margin'?'间隔分数':'模型分数'}}</span><strong>{{predictionResult.rows[0]?.score.toFixed(4)}}</strong></div></div></section>
<section v-show="activeTab==='history'" class="panel"><h2>切换记录</h2><el-table :data="historyRows" empty-text="暂无切换记录"><el-table-column label="范围 / 场景" min-width="190"><template #default="{row}">{{row.scopeKey}}</template></el-table-column><el-table-column label="原版本" min-width="180"><template #default="{row}">{{releaseName(row.previousId)}}</template></el-table-column><el-table-column label="切换至" min-width="180"><template #default="{row}">{{releaseName(row.releaseId)}}</template></el-table-column><el-table-column label="时间" min-width="180"><template #default="{row}">{{new Date(row.createdAt).toLocaleString('zh-CN')}}</template></el-table-column></el-table><RecordPagination v-model:current-page="historyPage" v-model:page-size="historySize" :total="historyTotal" @change="loadHistory" /></section></template>
<style scoped>.release-form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.release-form .el-select{width:100%}.release-pointers{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.release-pointers>div{border:1px solid var(--line);padding:20px;background:color-mix(in srgb,var(--el-color-primary) 6%,var(--canvas))}.release-pointers span{display:block;color:var(--muted);font-size:12px}.release-pointers strong{display:block;font-size:23px;margin-top:12px}.prediction-pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.link-gap{margin-left:18px}@media(max-width:1000px){.release-form{grid-template-columns:1fr 1fr}}@media(max-width:700px){.release-form,.release-pointers,.prediction-pair{grid-template-columns:1fr}}</style>
